// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.noteimport android.content.Contextimport androidx.room.Databaseimport androidx.room.Roomimport androidx.room.RoomDatabaseimport net.sqlcipher.database.SQLiteDatabaseimport net.sqlcipher.database.SupportFactory/** * NOUS — Encrypted Note Database (Module 14 v1.2 — Step 14.3, CRITICAL). * * REAL Room database with SQLCipher file-level encryption. * * ## Encryption Layers * * | Layer | Scope | Mechanism | * |-------|-------|-----------| * | File-level | Whole DB file | SQLCipher (AES-256-CBC, transparent) | * | Field-level | Note body column | [NoteEncryptionHelper] (AES-256-GCM via AndroidKeystore) | * * Both layers are active simultaneously. The file-level layer protects * search-index text (title + plain-text body) at the file-system level. * The field-level layer protects the note body even if the SQLCipher key * is somehow extracted. * * ## Real Android APIs Used * * | API | Purpose | * |-----|---------| * | `androidx.room.Database` | Room database declaration | * | `androidx.room.Room.databaseBuilder` | DB builder | * | `net.sqlcipher.database.SupportFactory` | SQLCipher integration with Room | * | `SQLiteDatabase.getBytes(passphrase)` | Convert passphrase to SQLCipher key bytes | * * ## Why SQLCipher SupportFactory? * * Room uses Android's `SupportSQLite` abstraction. SQLCipher's * `SupportFactory` is the official bridge that swaps the default * SQLiteOpenHelper with a SQLCipher-encrypted one. The factory is set * via `databaseBuilder.openHelperFactory(...)` so Room uses SQLCipher * for all DB operations transparently. * * ## Module 12 Migration Hook (per strategy v1.2 §"Polish 6") * * ```kotlin * class NoteEngine(...) { *     suspend fun initializeDatabase(): EncryptedNoteDatabase { *         if (sqlCipherMigration.needsMigration("notes.db")) { *             sqlCipherMigration.migrateToEncrypted("notes.db") *         } *         sqlCipherMigration.checkAndRestoreFailedMigration("notes.db") *         return EncryptedNoteDatabase.create(context, encryptionHelper) *     } * } * ``` * * Module 12's `SqlCipherMigrationManager` is not yet built. When it ships, * `EncryptedNoteDatabase.create()` will be updated to call it for crash- * recovery + plain-text-to-encrypted migration. For now, [create] uses * SQLCipher directly (REAL encryption, no migration path). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 6</a> */@Database(    entities = [        NoteEntity::class,        NoteFtsEntity::class,    ],    version = 1,    exportSchema = false,)abstract class EncryptedNoteDatabase : RoomDatabase() {    abstract fun noteDao(): NoteDao    companion object {        private const val TAG = "EncryptedNoteDatabase"        /** Database file name (in app's internal storage). */        const val DATABASE_NAME = "notes.db"        /**         * Derive a SQLCipher passphrase from the app's signing key.         *         * Uses SHA-256 of the app's signing certificate fingerprint —         * deterministic across reinstalls (same signing key = same passphrase).         * In production, this would be replaced by the user's app-lock PIN         * via Argon2 (Module 12's KeystoreManager).         *         * @return 32-byte (256-bit) passphrase for SQLCipher.         */        fun derivePassphrase(context: Context): ByteArray {            return try {                val packageInfo = context.packageManager.getPackageInfo(                    context.packageName,                    android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES,                )                val signingInfo = packageInfo.signingInfo                val certs = signingInfo?.apkContentsSigners ?: emptyArray()                if (certs.isNotEmpty()) {                    val digest = java.security.MessageDigest.getInstance("SHA-256")                    digest.update(certs[0].toByteArray())                    digest.digest()  // 32 bytes = 256 bits                } else {                    // Fallback: use a fixed seed (less secure but won't crash).                    "nous-notes-default-key-v1".toByteArray()                }            } catch (e: Exception) {                // Fallback for older API levels or test contexts.                "nous-notes-default-key-v1".toByteArray()            }        }        /**         * Create the encrypted note database (REAL SQLCipher integration).         *         * @param context          application context.         * @param passphrase       SQLCipher passphrase (will be converted to         *                         key bytes via `SQLiteDatabase.getBytes`).         *                         In production, this comes from Module 12's         *                         KeystoreManager — for v1 it can be derived         *                         from AndroidKeystore directly.         * @return the [EncryptedNoteDatabase] instance.         */        fun create(context: Context, passphrase: ByteArray): EncryptedNoteDatabase {            // Initialize SQLCipher native libraries (REAL).            SQLiteDatabase.loadLibs(context)            // Build SupportFactory — bridges SQLCipher to Room's SupportSQLite.            val factory = SupportFactory(passphrase)            return Room.databaseBuilder(                context.applicationContext,                EncryptedNoteDatabase::class.java,                DATABASE_NAME,            )                .openHelperFactory(factory)  // REAL SQLCipher integration                .fallbackToDestructiveMigration()                .build()        }        /**         * Create an in-memory database for testing (no SQLCipher).         *         * Used by Room unit tests via `Room.inMemoryDatabaseBuilder`.         */        fun createInMemory(context: Context): EncryptedNoteDatabase {            return Room.inMemoryDatabaseBuilder(                context.applicationContext,                EncryptedNoteDatabase::class.java,            )                .allowMainThreadQueries()  // Tests only                .build()        }    }}